package com.sami.app.purchasing.service;
import com.sami.app.accounting.publicapi.PayablePostingPort; import com.sami.app.common.exception.*; import com.sami.app.common.tenancy.TenantContext; import com.sami.app.organization.service.*; import lombok.RequiredArgsConstructor; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class SupplierInvoiceService {private final JdbcTemplate jdbc;private final TenantContext tenants;private final OrganizationScopeService scope;private final FoundationAuditService audit;private final Optional<PayablePostingPort> payable;
 @Transactional public Map<String,Object> create(Long company,Long branch,Long po,Long receipt,List<Map<String,Object>> lines,String notes){Long t=tenants.requireTenantId();scope.requireScope(company,branch);Map<String,Object> r=jdbc.queryForMap("select * from goods_receipts where tenant_id=? and id=? and purchase_order_id=? and status='CONFIRMED'",t,receipt,po);if(!Objects.equals(((Number)r.get("company_id")).longValue(),company)||!Objects.equals(((Number)r.get("branch_id")).longValue(),branch))throw new ApiException(ErrorCode.ACCESS_DENIED,"Receipt outside scope");if(lines==null||lines.isEmpty())throw new ApiException(ErrorCode.VALIDATION_FAILED,"Invoice requires lines");String n="SI-"+jdbc.queryForObject("select nextval('supplier_invoice_number_seq')",Long.class);Long id=jdbc.queryForObject("insert into supplier_invoices(tenant_id,company_id,branch_id,supplier_id,purchase_order_id,goods_receipt_id,invoice_number,invoice_date,notes) values(?,?,?,?,?,?,?,?,?) returning id",Long.class,t,company,branch,r.get("supplier_id"),po,receipt,n,LocalDate.now(),notes);BigDecimal total=BigDecimal.ZERO;for(Map<String,Object> l:lines){BigDecimal q=new BigDecimal(l.get("quantity").toString()),p=new BigDecimal(l.get("unitPrice").toString());Long gl=((Number)l.get("goodsReceiptLineId")).longValue();Map<String,Object> g=jdbc.queryForMap("select product_id,received_quantity from goods_receipt_lines where tenant_id=? and id=? and receipt_id=?",t,gl,receipt);if(q.signum()<=0||q.compareTo((BigDecimal)g.get("received_quantity"))>0)throw new ApiException(ErrorCode.VALIDATION_FAILED,"Invoice quantity exceeds receipt");BigDecimal v=q.multiply(p);total=total.add(v);jdbc.update("insert into supplier_invoice_lines(tenant_id,invoice_id,goods_receipt_line_id,product_id,quantity,unit_price,line_total) values(?,?,?,?,?,?,?)",t,id,gl,g.get("product_id"),q,p,v);}jdbc.update("update supplier_invoices set subtotal=?,total=?,status='ISSUED' where tenant_id=? and id=?",total,total,t,id);if(payable.isPresent()){String ref=payable.get().createPayable(new PayablePostingPort.PayableCommand(t,company,branch,((Number)r.get("supplier_id")).longValue(),id,total,"IRR",Instant.now(),"SUPPLIER-INVOICE-"+t+"-"+id));jdbc.update("update supplier_invoices set payable_posting_reference=? where tenant_id=? and id=?",ref,t,id);audit.record(t,company,branch,"SUPPLIER_INVOICE",id,"PAYABLE_POSTED",null,Map.of("reference",ref));}audit.record(t,company,branch,"SUPPLIER_INVOICE",id,"ISSUED",null,Map.of("goodsReceiptId",receipt,"total",total));return get(id);}
 @Transactional(readOnly=true) public Map<String,Object> get(Long id){Long t=tenants.requireTenantId();Map<String,Object> r=jdbc.queryForMap("select * from supplier_invoices where tenant_id=? and id=?",t,id);scope.requireScope(((Number)r.get("company_id")).longValue(),((Number)r.get("branch_id")).longValue());r.put("lines",jdbc.queryForList("select * from supplier_invoice_lines where tenant_id=? and invoice_id=?",t,id));return r;}
 @Transactional(readOnly=true) public List<Map<String,Object>> list(){Long t=tenants.requireTenantId();var c=scope.current();if(c.companyId()==null)return List.of();return c.branchId()==null?jdbc.queryForList("select * from supplier_invoices where tenant_id=? and company_id=? order by invoice_date desc",t,c.companyId()):jdbc.queryForList("select * from supplier_invoices where tenant_id=? and company_id=? and branch_id=? order by invoice_date desc",t,c.companyId(),c.branchId());}
 @Transactional public Map<String,Object> issue(Long id){Map<String,Object> r=get(id);if("ISSUED".equals(r.get("status")))return r;throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED,"Supplier invoice issue requires a payable-backed draft");}
}
